const CACHE='tokyo-station-game-fix-v1';
const FILES=['./game/ticket-session.js?v=fix1','./game/mobile-hud.css?v=fix1','./game/shoulder-camera.js?v=shoulder1','./game/avatar.css?v=avatar1','./game/avatar-catalog.js?v=avatar1','./game/avatar-layer.js?v=shoulder1','./game/avatars/block-person.glb','./game/avatars/block-person-blue.glb','./game/avatars/block-person-green.glb','./game/avatars/block-person-yellow.glb','./game/avatars/portraits.png','./vendor/avatar/GLTFLoader.js','./vendor/avatar/BufferGeometryUtils.js','./game/ticket.js?v=fix1','./game/ticket-state.js?v=ticket1','./game/ticket.css?v=avatar1','./','./index.html','./style.css','./guide-ui.css?v=game1','./app.js?v=fix1','./scene.js?v=game1','./station-layout.js?v=game1','./station-map.js?v=game1','./floor-layout.js?v=game1','./building-scene.js?v=game1','./train-data.js?v=game1','./train-scene.js?v=game1','./station-guide-data.js?v=game1','./gate-visuals.js?v=game1','./landmarks.js?v=game1','./landmark-scene.js?v=game1','./vendor/three.module.js','./icon.svg','./icon-180.png','./icon-192.png','./icon-512.png','./manifest.webmanifest','./game/studio.css?v=game1','./game/content.js?v=game1','./game/state.js?v=game1','./game/characters.js?v=game1','./game/addon.js?v=fix1'];
self.addEventListener('install',event=>{event.waitUntil(caches.open(CACHE).then(cache=>cache.addAll(FILES.map(path=>new Request(path,{cache:'reload'})))).then(()=>self.skipWaiting()))});
self.addEventListener('activate',event=>{event.waitUntil(caches.keys().then(keys=>Promise.all(keys.filter(key=>key.startsWith('tokyo-station-game-')&&key!==CACHE).map(key=>caches.delete(key)))).then(()=>self.clients.claim()))});
self.addEventListener('fetch',event=>{if(new URL(event.request.url).pathname.startsWith('/api/'))return;if(event.request.method!=='GET'||new URL(event.request.url).origin!==self.location.origin)return;event.respondWith(fetch(event.request,{cache:'no-cache'}).then(response=>{if(response.ok){const copy=response.clone();caches.open(CACHE).then(cache=>cache.put(event.request,copy))}return response}).catch(()=>caches.match(event.request).then(hit=>hit||new Response('オフラインで利用するには、初回にオンラインで開いてください。',{status:503,headers:{'Content-Type':'text/plain; charset=utf-8'}}))))});
